89	:root {
90	
91	  /* ---- Brand / Primitive: Greys ---- */
92	  --zimm-color-grey-black: black;
93	  --zimm-color-grey-900:   #191919;
94	  --zimm-color-grey-800:   #282828;
95	  --zimm-color-grey-700:   #454545;
96	  --zimm-color-grey-600:   #666;
97	  --zimm-color-grey-500:   #707070;
98	  --zimm-color-grey-300:   #969696;
99	  --zimm-color-grey-200:   #d1d1d1;
100	  --zimm-color-grey-100:   #e6e6e6;
101	  --zimm-color-grey-white: white;
102	
103	  /* ---- Brand / Primitive: Ivory ---- */
104	  --zimm-color-ivory-400: #f2e9e0;
105	  --zimm-color-ivory-300: #fbf5ef;
106	  --zimm-color-ivory-200: #f6f4f1;
107	  --zimm-color-ivory-100: #f9f8f6;
108	
109	  /* ---- Brand / Primitive: Status ---- */
110	  --zimm-color-coral-500:  #f98f8c;
111	  --zimm-color-green-500:  #2d5a3d;
112	  --zimm-color-orange-500: #d67600;
113	  --zimm-color-red-500:    #9c0000;
114	
115	  /* ---- Brand / Primitive: Opacity (base: grey/900 #191919) ---- */
116	  --zimm-color-opacity-50: rgba(25, 25, 25, 0.50);
117	  --zimm-color-opacity-40: rgba(25, 25, 25, 0.40);
118	  --zimm-color-opacity-30: rgba(25, 25, 25, 0.30);
119	  --zimm-color-opacity-15: rgba(25, 25, 25, 0.15);
120	
121	  /* ---- Alias / Semantic: Text ---- */
122	  --zimm-color-text-default:      var(--zimm-color-grey-900);
123	  --zimm-color-text-inverse:      var(--zimm-color-grey-white);
124	  --zimm-color-text-inverse-grey: #969696; /* confirmed: alias/color/text/inverse/subtle → brand/color/palette/natural/300 */
125	  --zimm-color-text-secondary:    var(--zimm-color-grey-600);
126	  --zimm-color-text-muted:        var(--zimm-color-grey-300);
127	
128	  /* ---- Alias / Semantic: Background ---- */
129	  --zimm-color-bg-01: var(--zimm-color-ivory-100);
130	  --zimm-color-bg-02: var(--zimm-color-ivory-200);
131	  --zimm-color-bg-03: var(--zimm-color-ivory-300);
132	  --zimm-color-bg-04: var(--zimm-color-ivory-400);
133	  --zimm-color-bg-05: var(--zimm-color-grey-900);
134	  --zimm-color-bg-06: var(--zimm-color-grey-800);
135	  --zimm-color-bg-07: var(--zimm-color-grey-white);
136	
137	  /* ---- Alias / Semantic: Border ---- */
138	  --zimm-color-border-default:   var(--zimm-color-grey-100);
139	  --zimm-color-border-secondary: var(--zimm-color-grey-200);
140	  --zimm-color-border-focus:     var(--zimm-color-grey-900);
141	  --zimm-color-border-forms:     var(--zimm-color-grey-500);
142	
143	  /* ---- Alias / Semantic: Status ---- */
144	  --zimm-color-status-success:      var(--zimm-color-green-500);
145	  --zimm-color-status-error:        var(--zimm-color-red-500);
146	  --zimm-color-status-error-bg:     var(--zimm-color-coral-500);
147	  --zimm-color-status-store-closed: var(--zimm-color-orange-500);
148	
149	  /* ---- Alias / Semantic: Link ---- */
150	  --zimm-color-link-default: var(--zimm-color-grey-900);
151	  --zimm-color-link-hover:   var(--zimm-color-grey-500);
152	
153	  /* ---- Alias / Semantic: Icon ---- */
154	  --zimm-color-icon-default: var(--zimm-color-grey-900);
155	
156	  /* ---- Alias / Semantic: Action: Primary ---- */
157	  --zimm-color-action-primary-bg-default:  var(--zimm-color-grey-900);
158	  --zimm-color-action-primary-bg-hover:    var(--zimm-color-grey-300);
159	  --zimm-color-action-primary-bg-pressed:  var(--zimm-color-grey-700);
160	  --zimm-color-action-primary-bg-disabled: var(--zimm-color-grey-200);
161	  --zimm-color-action-primary-bg-focused:  var(--zimm-color-grey-black);
162	  --zimm-color-action-primary-text:         var(--zimm-color-grey-white);
163	  --zimm-color-action-primary-text-disabled: var(--zimm-color-grey-300);
164	
165	  /* ---- Alias / Semantic: Action: Secondary ---- */
166	  --zimm-color-action-secondary-border:          var(--zimm-color-grey-900);
167	  --zimm-color-action-secondary-bg-hover:        var(--zimm-color-ivory-100);
168	  --zimm-color-action-secondary-text:            var(--zimm-color-grey-900);
169	  --zimm-color-action-secondary-text-inverse:    var(--zimm-color-grey-white);
170	  --zimm-color-action-secondary-text-disabled:   var(--zimm-color-grey-300);
171	
172	  /* ---- Typography: Font families ---- */
173	  --zimm-font-family-heading: 'Futura Round', sans-serif;
174	  --zimm-font-family-body:    'Futura Round', sans-serif;
175	  --zimm-font-family-serif:   'Source Serif 4', serif;
176	
177	  /* ---- Typography: Font sizes ---- */
178	  --zimm-font-size-md:  24px;
179	  --zimm-font-size-xs:  16px;
180	  --zimm-font-size-2xs: 14px;
181	  --zimm-font-size-3xs: 12px;
182	  --zimm-font-size-4xs: 10px;
183	
184	  /* ---- Typography: Line heights ---- */
185	  --zimm-font-lineheight-md:  32px;
186	  --zimm-font-lineheight-xs:  24px;
187	  --zimm-font-lineheight-2xs: 18px;
188	  --zimm-font-lineheight-3xs: 16px;
189	  --zimm-font-lineheight-4xs: 14px;
190	
191	  /* ---- Typography: Letter spacing ---- */
192	  --zimm-font-letterspacing-sm: 0px;
193	  --zimm-font-letterspacing-xs:     -0.12px;
194	  --zimm-font-letterspacing-footer:  0.4px;
195	
196	  /* ---- Typography: Font weights ---- */
197	  --zimm-font-weight-medium:  500;
198	  --zimm-font-weight-regular: 400;
199	
200	  /* ---- Spacing scale ---- */
201	  --zimm-scale-3xs:  2px;
202	  --zimm-scale-2xs:  4px;
203	  --zimm-scale-xs:   8px;
204	  --zimm-scale-s:    12px;
205	  --zimm-scale-m:    16px;
206	  --zimm-scale-l:    20px;
207	  --zimm-scale-xl:   24px;
208	  --zimm-scale-2xl:  32px;
209	  --zimm-scale-3xl:  40px;
210	  --zimm-scale-4xl:  64px;
211	  --zimm-scale-5xl:  80px;
212	  --zimm-scale-6xl:  128px;
213	  --zimm-scale-7xl:  160px;
214	
215	  /* ---- Spacing: numeric aliases (Figma scale token names -> named tokens) ---- */
216	  --zimm-scale-025:  1px;
217	  --zimm-scale-200:  var(--zimm-scale-xs);
218	  --zimm-scale-300:  var(--zimm-scale-s);
219	  --zimm-scale-400:  var(--zimm-scale-m);
220	  --zimm-scale-500:  var(--zimm-scale-l);
221	  --zimm-scale-600:  var(--zimm-scale-xl);
222	  --zimm-scale-700:  28px;
223	  --zimm-scale-800:  var(--zimm-scale-2xl);
224	  --zimm-scale-1000: var(--zimm-scale-3xl);
225	  --zimm-scale-1100: 44px;
226	  --zimm-scale-1200: 48px;
227	  --zimm-scale-1300: 52px;
228	  --zimm-scale-1600: var(--zimm-scale-4xl);
229	  --zimm-scale-3500: 140px;
230	  --zimm-scale-4500: 180px;
231	
232	  /* ---- Spacing: Grid margins ----
233	     NOTE (dev): These tokens define the outer horizontal padding for the layout grid at each breakpoint.
234	     Use --zimm-grid-margin-mobile / -tablet / -desktop anywhere a component needs to align with the grid
235	     edge (e.g. full-bleed cards, sticky panels). Do not hardcode 30px / 24px / 0 in component styles.
236	     Source: Figma grid definitions. No matching spacing-scale token exists for 30px or 24px.
237	     --------------------------------------------------------- */
238	  --zimm-grid-margin-mobile:  30px;
239	  --zimm-grid-margin-tablet:  24px;
240	  --zimm-grid-margin-desktop: 0px;
241	
242	  /* ---- Spacing: Action sizing (alias) ---- */
243	  --zimm-size-action-height-lg:    52px;
244	  --zimm-size-action-height-md:    40px;
245	  --zimm-size-action-padding-h-lg: 32px;
246	  --zimm-size-action-padding-h-md: 20px;
247	  --zimm-size-action-gap:          16px; /* Figma: --alias/space/action/gap/400 */
248	
249	  /* ---- Motion: PLACEHOLDER ----
250	     All transition and animation values below are provisional.
251	     Motion design is in progress and subject to change pending
252	     formal approval. Do not treat these values as final.
253	     --------------------------------------------------------- */
254	
255	  /* ---- Motion: Durations ---- */
256	  --zimm-motion-duration-fast:    200ms;
257	  --zimm-motion-duration-default: 300ms;
258	  --zimm-motion-duration-slow:    500ms;
259	
260	  /* ---- Motion: Easings ---- */
261	  --zimm-motion-easing-standard: ease;
262	  --zimm-motion-easing-slides:   cubic-bezier(0.87, 0, 0.13, 1);
263	  --zimm-motion-easing-fades:    cubic-bezier(0.37, 0, 0.63, 1);
264	
265	  /* ---- Border widths ---- */
266	  --zimm-border-width-default: 1px;
267	
268	  /* ---- Icon sizes ---- */
269	  --zimm-icon-size-lg: 20px;
270	  --zimm-icon-size-md: 16px;
271	  --zimm-icon-size-sm: 12px;
272	
273	}
