class ZimmButton extends HTMLElement {
  static get observedAttributes() {
    return ['variant', 'size', 'label', 'disabled', 'inverse', 'icon', 'type', 'full-width'];
  }

  constructor() {
    super();
    this.attachShadow({ mode: 'open' });
  }

  connectedCallback() { this._render(); }
  attributeChangedCallback(name, oldValue, newValue) { if (oldValue === newValue) return; this._render(); }

  _render() {
    const variant  = this.getAttribute('variant') || 'primary';

    if (variant === 'icon') {
      const icon      = this.getAttribute('icon') || '';
      const type      = this.getAttribute('type') || 'button';
      const label     = this.getAttribute('label') || icon;
      const disabled  = this.hasAttribute('disabled');
      const inv       = this.hasAttribute('inverse');
      const iconBase  = new URL('../icon/assets/', import.meta.url).href;
      const focusColor = inv ? 'var(--zimm-color-grey-white)' : 'var(--zimm-color-border-focus)';

      this.shadowRoot.innerHTML = `
        <style>
          :host { display: inline-block; }
          button {
            display: inline-flex;
            align-items: center;
            justify-content: center;
            background: none;
            border: none;
            padding: 8px;
            cursor: pointer;
            transition: opacity var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
          }
          button:hover:not(:disabled) { opacity: 0.6; }
          button:disabled { cursor: not-allowed; opacity: 0.4; }
          button:focus-visible {
            outline: 1px solid ${focusColor};
            outline-offset: 2px;
            border-radius: 2px;
          }
          img {
            display: block;
            width: 20px;
            height: 20px;
            ${inv ? 'filter: invert(1);' : ''}
          }
        </style>
        <button type="${type}" ${disabled ? 'disabled' : ''} aria-label="${label}">
          <img src="${iconBase}${icon}.svg" alt="" aria-hidden="true">
        </button>
      `;
      return;
    }


    const size     = this.getAttribute('size') || 'large';
    const label    = this.getAttribute('label') || 'Button';
    const disabled = this.hasAttribute('disabled');
    const inverse  = this.hasAttribute('inverse');

    const p   = variant === 'primary';
    const lg  = size === 'large';
    const inv = inverse;
    const fw  = this.hasAttribute('full-width');

    const bg    = p ? (inv ? 'var(--zimm-color-grey-white)'
                            : 'var(--zimm-color-action-primary-bg-default)')
                    : 'transparent';
    const color = p ? (inv ? 'var(--zimm-color-grey-900)'
                            : 'var(--zimm-color-action-primary-text)')
                    : (inv ? 'var(--zimm-color-grey-white)'
                            : 'var(--zimm-color-action-secondary-text)');
    const border = p ? 'none'
                     : `var(--zimm-border-width-default) solid ${inv ? 'var(--zimm-color-grey-white)' : 'var(--zimm-color-action-secondary-border)'}`;

    const hoverBg          = p ? (inv ? 'var(--zimm-color-ivory-100)' : 'var(--zimm-color-action-primary-bg-hover)')
                               : 'var(--zimm-color-action-secondary-bg-hover)';
    const hoverColor       = p ? (inv ? 'var(--zimm-color-grey-900)' : 'var(--zimm-color-action-primary-text)')
                               : 'var(--zimm-color-action-secondary-text)';
    const hoverBorderColor = !p ? (inv ? 'var(--zimm-color-grey-white)' : 'var(--zimm-color-action-secondary-border)') : '';

    const focusColor  = inv ? 'var(--zimm-color-grey-white)' : 'var(--zimm-color-border-focus)';
    const focusOffset = p ? '2px' : '3px';

    this.shadowRoot.innerHTML = `
      <style>
        :host { display: inline-block; }
        :host([full-width]) { display: block; width: 100%; }

        button {
          position: relative;
          display: inline-flex;
          ${fw ? 'width: 100%;' : ''}
          align-items: center;
          justify-content: center;
          gap: var(--zimm-size-action-gap);
          min-width: 80px;
          overflow: clip;
          cursor: pointer;
          font-family: var(--zimm-font-family-body);
          font-weight: var(--zimm-font-weight-medium);
          text-transform: uppercase;
          letter-spacing: var(--zimm-font-letterspacing-sm);
          transition: background-color 0.15s ease, color 0.15s ease, border-color 0.15s ease;

          height:      ${lg ? 'var(--zimm-size-action-height-lg)'      : 'var(--zimm-size-action-height-md)'};
          padding:     0 ${lg ? 'var(--zimm-size-action-padding-h-lg)' : 'var(--zimm-size-action-padding-h-md)'};
          font-size:   ${lg ? 'var(--zimm-font-size-2xs)'              : 'var(--zimm-font-size-3xs)'};
          line-height: ${lg ? 'var(--zimm-font-lineheight-3xs)'        : 'var(--zimm-font-lineheight-2xs)'};

          background: ${bg};
          color:      ${color};
          border:     ${border};
        }

        button:hover:not(:disabled) {
          background: ${hoverBg};
          color:      ${hoverColor};
          ${hoverBorderColor ? `border-color: ${hoverBorderColor};` : ''}
        }

        button:active:not(:disabled) {
          background: var(--zimm-color-action-primary-bg-pressed);
          color:      var(--zimm-color-action-secondary-text-inverse);
          ${!p ? 'border-color: var(--zimm-color-action-primary-bg-pressed);' : ''}
        }

        button:focus-visible {
          outline:        var(--zimm-border-width-default) solid ${focusColor};
          outline-offset: ${focusOffset};
        }

        button:disabled {
          cursor:       not-allowed;
          background:   ${p ? 'var(--zimm-color-action-primary-bg-disabled)' : 'transparent'};
          color:        ${p ? 'var(--zimm-color-action-primary-text-disabled)' : 'var(--zimm-color-action-secondary-text-disabled)'};
          border-color: ${p ? 'transparent' : 'var(--zimm-color-action-secondary-text-disabled)'};
        }
      </style>
      <button ${disabled ? 'disabled' : ''}>${label}</button>
    `;
  }
}

customElements.define('zimm-button', ZimmButton);

