/* ============================================================
   Template: Product Listing Page
   Spec: 02-design/specs/templates/template-product-listing.md
   Token source: library (../../../library/common.css)
   ============================================================ */

*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  padding: 0;
  background: var(--zimm-color-bg-07);
}

/* ---- Page shell ---- */
.page-shell {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 100vh;
}

.region {
  display: block;
  width: 100%;
}

/* ---- Sticky header ---- */
.region-header {
  position: sticky;
  top: 0;
  z-index: 100;
  transition: transform var(--zimm-motion-duration-default) var(--zimm-motion-easing-standard);
}

.region-header.is-hidden {
  transform: translateY(-100%);
}

/* ---- Sticky masthead ---- */
.masthead-wrap {
  position: sticky;
  top: 68px;
  transition: transform var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
}

.masthead-wrap.is-hidden {
  transform: translateY(calc(-100% - var(--nav-height, 68px)));
}

/* ---- Main content region ---- */
.region-content {
  background: var(--zimm-color-bg-07);
}

/* ---- Category links (light DOM, slotted into zimm-toolbar-category) ---- */
.cat-link {
  font-family:    var(--zimm-font-family-body);
  font-weight:    var(--zimm-font-weight-medium);
  font-size:      var(--zimm-font-size-2xs);
  line-height:    var(--zimm-font-lineheight-3xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
  color:          var(--zimm-color-text-default);
  text-decoration: none;
}

/* ---- Product grid ---- */
.product-grid-wrap {
  padding: 0 0 var(--zimm-scale-4xl) 0;
}

.product-grid {
  display:                   grid;
  grid-template-columns:     repeat(4, 1fr);
  column-gap:                100px;
  row-gap:                   var(--zimm-scale-4xl);
  --card-image-height:       auto;
  --card-image-aspect-ratio: 285 / 440; /* 285px card width : 440px height at 1440px, preserves ratio at any viewport */
}

zimm-product-showcase-blocks + .product-grid-wrap {
  padding-top: var(--zimm-scale-4xl);
}

/* ---- Product card image placeholder ---- */
.card-img-ph {
  display:      block;
  width:        100%;
  aspect-ratio: 285 / 440;
  background:   var(--zimm-color-bg-04);
}

/* ---- Product showcase blocks ---- */
/* --hero-width overrides the component default (664px) so the hero cell fills
   all available width beyond the fixed product grid (676px) + gap (100px). */
zimm-product-showcase-blocks {
  display: block;
  --hero-width: calc(100% - 776px);
}

.showcase-hero-img {
  display:    block;
  width:      100%;
  height:     1047px;
  background: var(--zimm-color-bg-02);
}

.showcase-product-img {
  display:    block;
  width:      100%;
  height:     380px;
  background: var(--zimm-color-bg-01);
}

/* ---- Pre-footer molecules ---- */

/* Video block placeholder */
.molecule-video {
  height:        920px;
  background:    var(--zimm-color-bg-01);
  margin-bottom: var(--zimm-scale-4xl);
}

/* Recently Viewed content placeholder (sits below zimm-page-toolbar) */
.molecule-recently-viewed {
  height:     560px;
  background: var(--zimm-color-bg-02);
}

/* ---- Mega menu: image placeholders ---- */
.img-ph              { width: 100%; height: 100%; display: block; }
.img-ph--new         { background: var(--zimm-color-bg-04); }
.img-ph--clothing    { background: var(--zimm-color-bg-02); }
.img-ph--accessories { background: var(--zimm-color-ivory-300); }
.img-ph--collections { background: var(--zimm-color-ivory-400); }

/* ---- Mega menu: collection column headings (slotted light DOM) ---- */
zimm-mega-menu [slot="links-heading"],
zimm-mega-menu [slot="links-2-heading"] {
  display:        block;
  font-family:    var(--zimm-font-family-body);
  font-weight:    var(--zimm-font-weight-medium);
  font-size:      var(--zimm-font-size-3xs);
  line-height:    var(--zimm-font-lineheight-3xs);
  letter-spacing: var(--zimm-font-letterspacing-footer);
  text-transform: uppercase;
  color:          var(--zimm-color-text-default);
  cursor:         default;
}

/* ---- Mega menu: link hover ---- */
@media (hover: hover) {
  zimm-mega-menu a[slot="links"]:hover,
  zimm-mega-menu a[slot="links-2"]:hover,
  zimm-mega-menu a[slot="all-link"]:hover {
    color: var(--zimm-color-text-secondary);
  }
}

/* ---- Mega menu: personalised product swatch ---- */
.ps {
  display:    flex;
  gap:        var(--zimm-scale-200);
  background: var(--zimm-color-bg-01);
  padding:    var(--zimm-scale-300);
  width:      210px;
  font-style: italic;
}
.ps-thumb {
  flex:         1;
  aspect-ratio: 3 / 4;
  background:   var(--zimm-color-bg-02);
}

/* ---- Mobile ---- */
@media (max-width: 767px) {
  .product-grid {
    grid-template-columns: repeat(2, 1fr);
    column-gap:            var(--zimm-scale-3xl);
  }
}

/* ---- Reduced motion ---- */
