/* ============================================================
   Template: Main Large Screen
   Spec: 02-design/specs/templates/template-main-large-screen.md
   Token source: library (../../../library/common.css)
   ============================================================ */

*, *::before, *::after { box-sizing: border-box; }

body {
  margin: 0;
  padding: 0;
  background: var(--zimm-color-grey-200);
}

/* Page shell: regions stacked flush, no gap. Each region owns its background */
.page-shell {
  display: flex;
  flex-direction: column;
  gap: 0;
  min-height: 100vh;
}

.region {
  display: block;
  width: 100%;
}

/* ---- Sticky header: slides up at 100px scroll, back in when reversed ---- */
.region-header {
  position: sticky;
  top: 0;
  z-index: 100;
  transition: transform var(--zimm-motion-duration-default) var(--zimm-motion-easing-standard);
}

.region-header.is-hidden {
  transform: translateY(-100%);
}

/* ---- Masthead: sticky below nav so it holds position during 0-80px ---- */
/* top is overridden by JS on load with the measured nav height */
.masthead-wrap {
  position: sticky;
  top: 68px; /* fallback, JS sets measured value on load */
  transition: transform var(--zimm-motion-duration-fast) var(--zimm-motion-easing-standard);
}

.masthead-wrap.is-hidden {
  /* -100% = own height, --nav-height = distance from viewport top to masthead top */
  transform: translateY(calc(-100% - var(--nav-height, 68px)));
}

/* ---- Main content region ---- */
.region-content {
  background: var(--zimm-color-grey-200);
}

/* TEMP: scroll demo placeholder. Remove when real content is added */
.placeholder-content {
  height: 100vh;
  background:
    repeating-linear-gradient(
      -45deg,
      transparent,
      transparent 40px,
      var(--zimm-color-grey-300) 40px,
      var(--zimm-color-grey-300) 41px
    );
  opacity: 0.4;
}

/* ---- Reduced motion ---- */
@media (prefers-reduced-motion: reduce) {
  .region-header,
  .masthead-wrap {
    transition: none;
  }
}

/* ---- Responsive ---- */
/* Navigation, Logo masthead, and Footer handle their own breakpoints internally via shadow DOM @media. */

/* ---- Mega menu: image placeholders ---- */
.img-ph {
  width: 100%;
  height: 100%;
  display: block;
}
.img-ph--new         { background: var(--zimm-color-bg-04); }
.img-ph--clothing    { background: var(--zimm-color-bg-02); }
.img-ph--accessories { background: var(--zimm-color-ivory-300); }
.img-ph--collections { background: var(--zimm-color-ivory-400); }

/* ---- Mega menu: collection column headings (slotted light DOM) ---- */
zimm-mega-menu [slot="links-heading"],
zimm-mega-menu [slot="links-2-heading"] {
  display: block;
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-3xs);
  letter-spacing: var(--zimm-font-letterspacing-footer);
  text-transform: uppercase;
  color: var(--zimm-color-text-default);
  cursor: default;
}

/* ---- Mega menu: link hover ---- */
@media (hover: hover) {
  zimm-mega-menu a[slot="links"]:hover,
  zimm-mega-menu a[slot="links-2"]:hover,
  zimm-mega-menu a[slot="all-link"]:hover {
    color: var(--zimm-color-text-secondary);
  }
}

/* ---- Mega menu: personalised product swatch ---- */
.ps {
  display: flex;
  gap: var(--zimm-scale-200);
  background: var(--zimm-color-bg-01);
  padding: var(--zimm-scale-300);
  width: 210px;
  font-style: italic;
}
.ps-thumb {
  flex: 1;
  aspect-ratio: 3 / 4;
  background: var(--zimm-color-bg-02);
}

