1	/* iOS Platform Styles
2	   Reference layer for iOS prototypes. Use alongside project tokens from common.css.
3	   Do not override library token values here, use these as guardrail references.
4	   Based on Apple Human Interface Guidelines.
5	   ------------------------------------------ */
6	
7	:root {
8	
9	  /* Typography
10	     SF Pro maps to -apple-system on Safari/WebKit (Apple devices).
11	     Falls back to Helvetica Neue in all other browsers. */
12	  --ios-font:         -apple-system, 'SF Pro Text', 'Helvetica Neue', Arial, sans-serif;
13	  --ios-font-display: -apple-system, 'SF Pro Display', 'Helvetica Neue', Arial, sans-serif;
14	
15	  /* Type scale (Dynamic Type, default size) */
16	  --ios-type-large-title:   34px;
17	  --ios-type-title-1:       28px;
18	  --ios-type-title-2:       22px;
19	  --ios-type-title-3:       20px;
20	  --ios-type-headline:      17px; /* semibold */
21	  --ios-type-body:          17px;
22	  --ios-type-callout:       16px;
23	  --ios-type-subheadline:   15px; /* semibold */
24	  --ios-type-footnote:      13px;
25	  --ios-type-caption-1:     12px;
26	  --ios-type-caption-2:     11px;
27	
28	  /* System colours (light mode) */
29	  --ios-blue:    #007AFF;
30	  --ios-green:   #34C759;
31	  --ios-indigo:  #5856D6;
32	  --ios-orange:  #FF9500;
33	  --ios-pink:    #FF2D55;
34	  --ios-purple:  #AF52DE;
35	  --ios-red:     #FF3B30;
