/* iOS Platform Styles
   Reference layer for iOS prototypes. Use alongside project tokens from common.css.
   Do not override library token values here, use these as guardrail references.
   Based on Apple Human Interface Guidelines.
   ------------------------------------------ */

:root {

  /* Typography
     SF Pro maps to -apple-system on Safari/WebKit (Apple devices).
     Falls back to Helvetica Neue in all other browsers. */
  --ios-font:         -apple-system, 'SF Pro Text', 'Helvetica Neue', Arial, sans-serif;
  --ios-font-display: -apple-system, 'SF Pro Display', 'Helvetica Neue', Arial, sans-serif;

  /* Type scale (Dynamic Type, default size) */
  --ios-type-large-title:   34px;
  --ios-type-title-1:       28px;
  --ios-type-title-2:       22px;
  --ios-type-title-3:       20px;
  --ios-type-headline:      17px; /* semibold */
  --ios-type-body:          17px;
  --ios-type-callout:       16px;
  --ios-type-subheadline:   15px; /* semibold */
  --ios-type-footnote:      13px;
  --ios-type-caption-1:     12px;
  --ios-type-caption-2:     11px;

  /* System colours (light mode) */
  --ios-blue:    #007AFF;
  --ios-green:   #34C759;
  --ios-indigo:  #5856D6;
  --ios-orange:  #FF9500;
  --ios-pink:    #FF2D55;
  --ios-purple:  #AF52DE;
  --ios-red:     #FF3B30;
  --ios-teal:    #5AC8FA;
  --ios-yellow:  #FFCC00;
  --ios-gray:    #8E8E93;
  --ios-gray-2:  #AEAEB2;
  --ios-gray-3:  #C7C7CC;
  --ios-gray-4:  #D1D1D6;
  --ios-gray-5:  #E5E5EA;
  --ios-gray-6:  #F2F2F7;

  /* Backgrounds */
  --ios-bg-primary:   #FFFFFF;
  --ios-bg-secondary: #F2F2F7;
  --ios-bg-tertiary:  #FFFFFF;

  /* Labels */
  --ios-label:            #000000;
  --ios-label-secondary:  rgba(60, 60, 67, 0.6);
  --ios-label-tertiary:   rgba(60, 60, 67, 0.3);
  --ios-label-quaternary: rgba(60, 60, 67, 0.18);
  --ios-label-inverted:   #FFFFFF;

  /* Fills */
  --ios-fill:          rgba(120, 120, 128, 0.2);
  --ios-fill-secondary: rgba(120, 120, 128, 0.16);
  --ios-fill-tertiary:  rgba(118, 118, 128, 0.12);
  --ios-fill-quaternary: rgba(116, 116, 128, 0.08);

  /* Separators */
  --ios-separator:        rgba(60, 60, 67, 0.29);
  --ios-separator-opaque: #C6C6C8;

  /* Spacing (4pt base grid) */
  --ios-space-xs:  4px;
  --ios-space-sm:  8px;
  --ios-space-md:  16px;
  --ios-space-lg:  20px;
  --ios-space-xl:  24px;
  --ios-space-2xl: 32px;
  --ios-space-3xl: 44px;

  /* Component dimensions */
  --ios-nav-bar-height:    44px;
  --ios-tab-bar-height:    49px;
  --ios-status-bar-height: 44px;
  --ios-touch-target:      44px;
  --ios-radius-sm:         8px;
  --ios-radius-md:         12px;
  --ios-radius-lg:         16px;
  --ios-radius-xl:         20px;
  --ios-radius-full:       9999px;
}


/* Base */

*, *::before, *::after { box-sizing: border-box; }

body {
  font-family: var(--ios-font);
  font-size: var(--ios-type-body);
  color: var(--ios-label);
  background: var(--ios-bg-secondary);
  -webkit-font-smoothing: antialiased;
  margin: 0;
}


/* Device wrapper
   Wrap your prototype in .ios-device to simulate a 390x844 viewport (iPhone 14 base). */

.ios-device {
  width: 390px;
  min-height: 844px;
  overflow: hidden;
  position: relative;
  background: var(--ios-bg-secondary);
  padding-top: env(safe-area-inset-top, 44px);
  padding-bottom: env(safe-area-inset-bottom, 34px);
}


/* Navigation bar */

.ios-nav-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: var(--ios-nav-bar-height);
  padding: 0 var(--ios-space-md);
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-bottom: 0.5px solid var(--ios-separator);
  position: sticky;
  top: 0;
  z-index: 100;
}

.ios-nav-bar__title {
  font-size: var(--ios-type-headline);
  font-weight: 600;
  color: var(--ios-label);
}

.ios-nav-bar__action {
  min-width: var(--ios-touch-target);
  min-height: var(--ios-touch-target);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--ios-type-body);
  color: var(--ios-blue);
  background: none;
  border: none;
  padding: 0;
  cursor: pointer;
}


/* Tab bar */

.ios-tab-bar {
  display: flex;
  align-items: flex-start;
  justify-content: space-around;
  height: var(--ios-tab-bar-height);
  padding-top: var(--ios-space-xs);
  background: rgba(255, 255, 255, 0.85);
  backdrop-filter: blur(20px);
  -webkit-backdrop-filter: blur(20px);
  border-top: 0.5px solid var(--ios-separator);
  position: sticky;
  bottom: 0;
}

.ios-tab-bar__item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: var(--ios-touch-target);
  color: var(--ios-gray);
  font-size: var(--ios-type-caption-2);
  cursor: pointer;
}

.ios-tab-bar__item--active { color: var(--ios-blue); }


/* Content */

.ios-content {
  padding: var(--ios-space-md);
}


/* List / table view */

.ios-list {
  background: var(--ios-bg-primary);
  border-radius: var(--ios-radius-lg);
  overflow: hidden;
  margin: var(--ios-space-md) 0;
}

.ios-list__item {
  display: flex;
  align-items: center;
  min-height: var(--ios-touch-target);
  padding: var(--ios-space-md);
  border-bottom: 0.5px solid var(--ios-separator);
  background: var(--ios-bg-primary);
}

.ios-list__item:last-child { border-bottom: none; }

.ios-list__label { font-size: var(--ios-type-body); color: var(--ios-label); }
.ios-list__detail { font-size: var(--ios-type-body); color: var(--ios-label-secondary); }


/* Buttons */

.ios-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--ios-touch-target);
  padding: 0 var(--ios-space-xl);
  border-radius: var(--ios-radius-lg);
  font-family: var(--ios-font);
  font-size: var(--ios-type-body);
  font-weight: 400;
  border: none;
  cursor: pointer;
  transition: opacity 100ms ease;
}

.ios-btn:active { opacity: 0.6; }

.ios-btn--primary    { background: var(--ios-blue);  color: #fff; }
.ios-btn--secondary  { background: var(--ios-gray-5); color: var(--ios-blue); }
.ios-btn--destructive { background: var(--ios-red); color: #fff; }
.ios-btn--ghost      { background: none; color: var(--ios-blue); padding: 0; }
.ios-btn--full       { width: 100%; }


/* Sheet / modal */

.ios-sheet {
  background: var(--ios-bg-primary);
  border-radius: var(--ios-radius-xl) var(--ios-radius-xl) 0 0;
  padding: var(--ios-space-xl) var(--ios-space-md);
  position: relative;
}

.ios-sheet::before {
  content: '';
  display: block;
  width: 36px;
  height: 5px;
  border-radius: var(--ios-radius-full);
  background: var(--ios-gray-3);
  margin: 0 auto var(--ios-space-xl);
}


/* Section header */

.ios-section-header {
  padding: var(--ios-space-sm) var(--ios-space-md) var(--ios-space-xs);
  font-size: var(--ios-type-footnote);
  font-weight: 400;
  color: var(--ios-label-secondary);
  text-transform: uppercase;
  letter-spacing: 0.03em;
}

