/* Android / Material Design 3 Platform Styles
   Reference layer for Android prototypes. Use alongside project tokens from common.css.
   Do not override library token values here, use these as guardrail references.
   Based on Material Design 3 (Material You).
   ------------------------------------------ */

:root {

  /* Typography
     Roboto and Google Sans are used here. Product Sans is not publicly available. */
  --md-font:         'Roboto', 'Google Sans', 'Noto Sans', Arial, sans-serif;
  --md-font-display: 'Google Sans', 'Roboto', Arial, sans-serif;

  /* M3 type scale */
  --md-type-display-large:   57px;
  --md-type-display-medium:  45px;
  --md-type-display-small:   36px;
  --md-type-headline-large:  32px;
  --md-type-headline-medium: 28px;
  --md-type-headline-small:  24px;
  --md-type-title-large:     22px;
  --md-type-title-medium:    16px;
  --md-type-title-small:     14px;
  --md-type-label-large:     14px;
  --md-type-label-medium:    12px;
  --md-type-label-small:     11px;
  --md-type-body-large:      16px;
  --md-type-body-medium:     14px;
  --md-type-body-small:      12px;

  /* Colour roles (M3 baseline, light scheme) */
  --md-primary:               #6750A4;
  --md-on-primary:            #FFFFFF;
  --md-primary-container:     #EADDFF;
  --md-on-primary-container:  #21005D;
  --md-secondary:             #625B71;
  --md-on-secondary:          #FFFFFF;
  --md-secondary-container:   #E8DEF8;
  --md-on-secondary-container: #1D192B;
  --md-tertiary:              #7D5260;
  --md-on-tertiary:           #FFFFFF;
  --md-tertiary-container:    #FFD8E4;
  --md-on-tertiary-container: #31111D;
  --md-error:                 #B3261E;
  --md-on-error:              #FFFFFF;
  --md-error-container:       #F9DEDC;
  --md-on-error-container:    #410E0B;
  --md-surface:               #FEF7FF;
  --md-on-surface:            #1C1B1F;
  --md-surface-variant:       #E7E0EC;
  --md-on-surface-variant:    #49454F;
  --md-surface-container-lowest:  #FFFFFF;
  --md-surface-container-low:     #F7F2FA;
  --md-surface-container:         #F3EDF7;
  --md-surface-container-high:    #ECE6F0;
  --md-surface-container-highest: #E6E0E9;
  --md-outline:               #79747E;
  --md-outline-variant:       #CAC4D0;
  --md-background:            #FEF7FF;
  --md-on-background:         #1C1B1F;
  --md-scrim:                 #000000;

  /* Spacing (4dp grid) */
  --md-space-1:  4px;
  --md-space-2:  8px;
  --md-space-3:  12px;
  --md-space-4:  16px;
  --md-space-5:  20px;
  --md-space-6:  24px;
  --md-space-8:  32px;
  --md-space-10: 40px;
  --md-space-12: 48px;

  /* Shape (M3 corner radius scale) */
  --md-shape-none: 0px;
  --md-shape-xs:   4px;
  --md-shape-sm:   8px;
  --md-shape-md:   12px;
  --md-shape-lg:   16px;
  --md-shape-xl:   28px;
  --md-shape-full: 9999px;

  /* Component dimensions */
  --md-app-bar-height:  64px;
  --md-nav-bar-height:  80px;
  --md-touch-target:    48px;
  --md-fab-size:        56px;
  --md-fab-size-small:  40px;
  --md-fab-size-large:  96px;
}


/* Base */

*, *::before, *::after { box-sizing: border-box; }

body {
  font-family: var(--md-font);
  font-size: var(--md-type-body-large);
  color: var(--md-on-background);
  background: var(--md-background);
  -webkit-font-smoothing: antialiased;
  margin: 0;
}


/* Device wrapper
   Wrap your prototype in .android-device to simulate a 360x800 viewport (common Android base). */

.android-device {
  width: 360px;
  min-height: 800px;
  overflow: hidden;
  position: relative;
  background: var(--md-background);
}


/* Top App Bar */

.md-app-bar {
  display: flex;
  align-items: center;
  height: var(--md-app-bar-height);
  padding: 0 var(--md-space-4);
  gap: var(--md-space-2);
  background: var(--md-surface);
  color: var(--md-on-surface);
}

.md-app-bar__title {
  font-size: var(--md-type-title-large);
  font-weight: 400;
  flex: 1;
}

.md-app-bar__icon {
  width: var(--md-touch-target);
  height: var(--md-touch-target);
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: var(--md-shape-full);
  background: none;
  border: none;
  color: var(--md-on-surface-variant);
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.md-app-bar__icon::after {
  content: '';
  position: absolute;
  inset: 0;
  background: currentColor;
  opacity: 0;
  border-radius: inherit;
  transition: opacity 200ms ease;
}

.md-app-bar__icon:hover::after { opacity: 0.08; }
.md-app-bar__icon:active::after { opacity: 0.12; }


/* Navigation Bar (bottom) */

.md-nav-bar {
  display: flex;
  height: var(--md-nav-bar-height);
  background: var(--md-surface-container);
  border-top: 1px solid var(--md-outline-variant);
  position: sticky;
  bottom: 0;
}

.md-nav-bar__item {
  flex: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--md-space-1);
  padding: var(--md-space-3) 0 var(--md-space-4);
  font-size: var(--md-type-label-medium);
  font-weight: 500;
  color: var(--md-on-surface-variant);
  cursor: pointer;
}

.md-nav-bar__item--active { color: var(--md-on-secondary-container); }

.md-nav-bar__indicator {
  width: 64px;
  height: 32px;
  border-radius: var(--md-shape-full);
  display: flex;
  align-items: center;
  justify-content: center;
}

.md-nav-bar__item--active .md-nav-bar__indicator {
  background: var(--md-secondary-container);
}


/* Content */

.md-content {
  padding: var(--md-space-4);
}


/* Buttons */

.md-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: var(--md-touch-target);
  padding: 0 var(--md-space-6);
  border-radius: var(--md-shape-full);
  font-family: var(--md-font);
  font-size: var(--md-type-label-large);
  font-weight: 500;
  letter-spacing: 0.1px;
  border: none;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: box-shadow 200ms ease;
}

.md-btn::after {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background: currentColor;
  opacity: 0;
  transition: opacity 200ms ease;
}

.md-btn:hover::after  { opacity: 0.08; }
.md-btn:active::after { opacity: 0.12; }

.md-btn--filled   { background: var(--md-primary); color: var(--md-on-primary); box-shadow: 0 1px 2px rgba(0,0,0,0.3), 0 1px 3px 1px rgba(0,0,0,0.15); }
.md-btn--tonal    { background: var(--md-secondary-container); color: var(--md-on-secondary-container); }
.md-btn--outlined { background: transparent; color: var(--md-primary); border: 1px solid var(--md-outline); }
.md-btn--elevated { background: var(--md-surface-container-low); color: var(--md-primary); box-shadow: 0 1px 2px rgba(0,0,0,0.3), 0 1px 3px 1px rgba(0,0,0,0.15); }
.md-btn--text     { background: none; color: var(--md-primary); padding: 0 var(--md-space-3); }


/* FAB */

.md-fab {
  width: var(--md-fab-size);
  height: var(--md-fab-size);
  border-radius: var(--md-shape-lg);
  background: var(--md-primary-container);
  color: var(--md-on-primary-container);
  display: flex;
  align-items: center;
  justify-content: center;
  box-shadow: 0 1px 2px rgba(0,0,0,0.3), 0 2px 6px 2px rgba(0,0,0,0.15);
  border: none;
  cursor: pointer;
  position: relative;
  overflow: hidden;
}

.md-fab::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--md-on-primary-container);
  opacity: 0;
  border-radius: inherit;
  transition: opacity 200ms ease;
}

.md-fab:hover::after  { opacity: 0.08; }
.md-fab:active::after { opacity: 0.12; }


/* Cards */

.md-card {
  border-radius: var(--md-shape-md);
  overflow: hidden;
  position: relative;
}

.md-card--elevated {
  background: var(--md-surface-container-low);
  box-shadow: 0 1px 2px rgba(0,0,0,0.3), 0 1px 3px 1px rgba(0,0,0,0.15);
}

.md-card--filled   { background: var(--md-surface-container-highest); }
.md-card--outlined { background: var(--md-surface); border: 1px solid var(--md-outline-variant); }


/* List */

.md-list__item {
  display: flex;
  align-items: center;
  min-height: var(--md-touch-target);
  padding: var(--md-space-3) var(--md-space-4);
  gap: var(--md-space-4);
  color: var(--md-on-surface);
  position: relative;
  cursor: pointer;
}

.md-list__item::after {
  content: '';
  position: absolute;
  inset: 0;
  background: var(--md-on-surface);
  opacity: 0;
  transition: opacity 200ms ease;
}

.md-list__item:hover::after  { opacity: 0.08; }
.md-list__item:active::after { opacity: 0.12; }

.md-list__headline      { font-size: var(--md-type-body-large); }
.md-list__supporting    { font-size: var(--md-type-body-medium); color: var(--md-on-surface-variant); }


/* Chips */

.md-chip {
  display: inline-flex;
  align-items: center;
  height: 32px;
  padding: 0 var(--md-space-4);
  border-radius: var(--md-shape-sm);
  font-size: var(--md-type-label-large);
  font-weight: 500;
  gap: var(--md-space-2);
  cursor: pointer;
  border: 1px solid var(--md-outline-variant);
  background: none;
  color: var(--md-on-surface-variant);
  position: relative;
  overflow: hidden;
}

.md-chip--selected {
  background: var(--md-secondary-container);
  color: var(--md-on-secondary-container);
  border-color: transparent;
}


/* Divider */

.md-divider {
  height: 1px;
  background: var(--md-outline-variant);
  border: none;
  margin: 0;
}

